package com.skirmishchronicle.table.geo;

import static org.junit.jupiter.api.Assertions.assertEquals;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.jupiter.api.Test;

/**
 * The browser previews movement and LoS with frontend/src/lib/table/geometry.ts; the server decides with
 * {@link Geometry}. Both must agree: vectors.json is generated by the TS engine (make-vectors.ts).
 */
class GeometryParityTest {

    @Test
    void javaGeometryMatchesTheBrowserEngine() throws Exception {
        JsonNode root;
        try (InputStream in = getClass().getResourceAsStream("/table/vectors.json")) {
            root = new ObjectMapper().readTree(in);
        }
        int moves = 0, los = 0;
        for (JsonNode s : root.get("scenarios")) {
            Table table = table(s.get("table"));
            for (JsonNode m : s.get("moves")) {
                String id = m.get("piece").asText();
                Geometry.MoveMode mode = Geometry.MoveMode.valueOf(m.get("mode").asText());
                List<Vec> wps = new ArrayList<>();
                m.get("waypoints").forEach(w -> wps.add(vec(w)));
                MovePlan p = Geometry.planMove(table, id, wps, Geometry.moveBudget(table.piece(id), mode));
                JsonNode e = m.get("expect");
                String ctx = "move " + moves + " of " + id;
                assertEquals(e.get("end").get("x").asDouble(), p.end().x(), 0.01, ctx + " end.x");
                assertEquals(e.get("end").get("y").asDouble(), p.end().y(), 0.01, ctx + " end.y");
                assertEquals(e.get("cost").asDouble(), p.cost(), 0.02, ctx + " cost");
                assertEquals(text(e.get("stoppedBy")), p.stoppedBy() == null ? null : p.stoppedBy().kind(), ctx + " stoppedBy");
                assertEquals(text(e.get("engagedWith")), p.engagedWith(), ctx + " engaged");
                assertEquals(text(e.get("endsOnAlly")), p.endsOnAlly(), ctx + " ally");
                moves++;
            }
            for (JsonNode l : s.get("los")) {
                Geometry.Los r = Geometry.lineOfSight(table, l.get("from").asText(), l.get("to").asText(), false);
                String ctx = "los " + los + " " + l.get("from").asText() + "->" + l.get("to").asText();
                assertEquals(l.get("visible").asBoolean(), r.visible(), ctx);
                assertEquals(text(l.get("reason")), r.reason(), ctx + " reason");
                los++;
            }
        }
        assertEquals(160, moves);
        assertEquals(240, los);
    }

    private static String text(JsonNode n) {
        return n == null || n.isNull() ? null : n.asText();
    }

    private static Vec vec(JsonNode n) {
        return new Vec(n.get("x").asDouble(), n.get("y").asDouble());
    }

    private static Table table(JsonNode t) {
        List<Terrain> terrain = new ArrayList<>();
        for (JsonNode n : t.get("terrain")) {
            List<Vec> pts = new ArrayList<>();
            n.get("points").forEach(p -> pts.add(vec(p)));
            Set<Env> envs = new HashSet<>();
            n.get("envs").forEach(e -> envs.add(Env.valueOf(e.asText())));
            terrain.add(new Terrain(n.get("id").asText(), Terrain.Kind.valueOf(n.get("kind").asText()), pts,
                    n.get("height").asDouble(), envs));
        }
        List<Piece> pieces = new ArrayList<>();
        for (JsonNode n : t.get("pieces")) {
            Set<String> kw = new HashSet<>(), st = new HashSet<>();
            n.get("keywords").forEach(k -> kw.add(k.asText()));
            n.get("states").forEach(k -> st.add(k.asText()));
            pieces.add(new Piece(n.get("id").asText(), n.get("side").asText().equals("A") ? 0 : 1, vec(n.get("pos")),
                    n.get("facing").asDouble(), Size.valueOf(n.get("size").asText()), n.get("spd").asDouble(),
                    n.get("ag").asInt(), n.get("faction").asText(), kw, st));
        }
        return new Table(t.get("width").asDouble(), t.get("height").asDouble(), terrain, pieces);
    }
}
